import pathlib,json,gzip,re,collections,hashlib
R=pathlib.Path('test-results/perf9');rows=[]
for context,pattern in [('L7 high warm load','diagnostic/load-high-L7/loads/L7-{}-warm.cpuprofile.gz'),('L10 high early charge','diagnostic/L10-early/strips/webgpu/L10-{}.cpuprofile.gz'),('L4 low early war','diagnostic/L4-early/strips/webgpu/L4-{}.cpuprofile.gz')]:
 for side,bundle in [('prod',R/'prod/build/index-DbFAIX8_.js'),('candidate',pathlib.Path('dist/build/index-DnjIp4Ne.js'))]:
  text=bundle.read_text();m=re.search(r'function ([\w$]+)\([^)]*\)\{const \w+=!!\w+\.prone',text);repair=m.group(1) if m else None;m=re.search(r'function ([\w$]+)\([^)]*\)\{const \w+=\w+\.binds,\w+=\w+\.matrices',text);skin=m.group(1)
  p=R/pattern.format(side);v=json.loads(gzip.decompress(p.read_bytes()));nodes={n['id']:n for n in v['nodes']};parents={c:n['id'] for n in v['nodes'] for c in n.get('children',[])};cpu=collections.Counter()
  for sample,dt in zip(v['samples'],v['timeDeltas']):
   names=[];n=sample
   while n:names.append(nodes[n]['callFrame']['functionName']);n=parents.get(n)
   if repair and repair in names:cpu['repairInclusiveMs']+=dt/1000
   if names[0]==skin:cpu['skinInRepairMs' if repair and repair in names else 'skinInFrozenMs' if 'frozenPose' in names else 'skinOtherMs']+=dt/1000
  row=dict(context=context,side=side,source=str(p),sourceSha256=hashlib.sha256(p.read_bytes()).hexdigest(),bundleSha256=hashlib.sha256(bundle.read_bytes()).hexdigest(),repairSymbol=repair,skinSymbol=skin,cpu=dict(cpu));rows.append(row);print(row)
(R/'profile-attribution.json').write_text(json.dumps(rows,indent=2))

