import json,pathlib,hashlib,math,datetime,collections,subprocess
O=pathlib.Path('docs/reports/perf9');R=pathlib.Path('test-results/perf9');checks=[]
def read(n):return json.loads((O/n).read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def check(ok,msg):
 if not ok:raise AssertionError(msg)
 checks.append(msg)
def stats(a):return dict(samples=len(a),p95=sorted(a)[math.ceil(.95*len(a))-1],maximum=max(a),spikes66=sum(v>=66-1e-6 for v in a))
levels=['L1','L3','L4','L5','L7','L10'];prov=read('provenance.json');req=read('request-audit.json');verdictSets={}
def audit_dataset(prefix,candidateBundle,extra):
 matrix=read(prefix+'matrix.json');loads=read(prefix+'loads.json');native=read(prefix+'native.json')
 expected={(b,l,t,s,temp) for b,l,t in [('webgpu',l,t) for l in levels for t in ['low','high']]+[('webgl2',l,'low') for l in ['L1','L4','L7']] for s in ['prod','candidate'] for temp in ['cold','warm']}
 check(len(loads)==60 and {(r['backend'],r['level'],r['tier'],r['side'],r['temperature']) for r in loads}==expected,'all 60 unique requested load phases')
 check(len(native)==24 and {(r['level'],r['tier'],r['side']) for r in native}=={(l,t,s) for l in levels for t in ['low','high'] for s in ['prod','candidate']},'all 24 unique native captures')
 for r in loads:
  key=f"{r['side']} {r['backend']} {r['level']} {r['tier']} {r['temperature']}"
  check(not r['errors'] and r['quality']==r['tier'] and r['ms']>0 and abs(r['ms']-(r['done']-r['start']))<1e-8,'valid exact menu duration '+key)
  if r['backend']=='webgpu':check('webgpu' in r['contexts'] and r['adapter']['vendor']=='apple' and not r['adapter']['fallback'],'native WebGPU load '+key)
  else:check('webgl2' in r['contexts'] and 'webgpu' not in r['contexts'] and 'Metal' in r['glRenderer'],'native Metal WebGL2 load '+key)
  bundle='index-DbFAIX8_.js' if r['side']=='prod' else candidateBundle;port=4902 if r['side']=='prod' else 4901
  check(r['bundle']==f'http://127.0.0.1:{port}/build/{bundle}','public bundle '+key)
  check(set(r['networkStatuses'])<=set(['200','304']),'load request success '+key)
 for r in native+extra:
  f=r['performance'];key=f"{r['side']} {r['level']} {r['tier']}"
  check(not r['errors'] and not r.get('failure') and not r['diagnostic'] and f['nonGameplayFrames']==0,'valid native boundaries/errors '+key)
  check(f['durationMs']>=60000 and sum(f['frames'])>=60000 and all(x>0 for x in f['frames']),'complete physical frame minute '+key)
  v=stats(f['frames']);check(v['p95']==f['p95Ms'] and v['maximum']==f['maxMs'],'exact frame statistics '+key)
  check(r['hardware']['vendor']=='apple' and not r['hardware']['isFallbackAdapter'] and all(s['backend']=='webgpu' and s['quality']==r['tier'] and s['scenario']==r['level'] and not s['loading'] for s in r['samples']),'native GPU/tier/level '+key)
  if r['level'] in ['L1','L7','L10']:check(len(f['frames'])==len(f['missionFrames'] if r['level']!='L10' else f['chargeFrames']),'per-frame mission alignment '+key)
  if r['level']=='L1':check(r['nativeBeat']['state']['l1']['handoverAt']==0,'L1 begins before handover '+key)
  if r['level']=='L7':check(not f['missionFrames'][0]['started'],'L7 begins before pickup '+key)
  if r['level']=='L10' and r['tier']=='high':check(f['durationMs']>=90000 and max(x['charge'] for x in f['chargeFrames'])>=3600,'L10 full charge and 90 seconds '+key)
  check(r['inputFrames']>=3000,'ordinary native input coverage '+key)
 check(len(matrix['matrix'])==15,'15 requested verdict cells')
 for row in matrix['matrix']:
  issues=[]
  for temp in ['cold','warm']:
   p,c=(next(x['ms'] for x in loads if (x['side'],x['backend'],x['level'],x['tier'],x['temperature'])==(side,row['backend'],row['level'],row['tier'],temp)) for side in ['prod','candidate'])
   check(row['loads']['prod'][temp]==p and row['loads']['candidate'][temp]==c,'matrix load values '+str((row['backend'],row['level'],row['tier'],temp)))
   if c>6000:issues.append(temp+': >6 s')
   if c>p+500:issues.append(temp+': >PROD+0.5 s')
  if row['backend']=='webgpu':
   p,c=(stats(next(x['performance']['frames'] for x in native if (x['side'],x['level'],x['tier'])==(side,row['level'],row['tier']))) for side in ['prod','candidate'])
   check(row['native']['prod']==p and row['native']['candidate']==c,'matrix exact frame values '+str((row['level'],row['tier'])))
   if c['p95']>p['p95']+1+1e-6:issues.append('p95 > PROD+1 ms')
   if c['maximum']>p['maximum']+16.8+1e-6:issues.append('max > PROD+1 frame')
   if c['maximum']>=66-1e-6 and p['maximum']<66-1e-6:issues.append('new >=66 ms spike')
  check(row['issues']==issues and row['verdict']==('FAIL' if issues else 'PASS'),'independent cell verdict '+str((row['backend'],row['level'],row['tier'])))
 check(len(matrix['moments'])==9,'all 9 requested-tier event/charge windows')
 for row in matrix['moments']:
  values={}
  for side in ['prod','candidate']:
   r=next(x for x in native+extra if (x['side'],x['level'],x['tier'],x['rawSource'])==(side,row['level'],row['tier'],row['windows'][side]['rawSource']));f=r['performance'];events=r['events'];kind=row['name']
   if row['level']=='L1':
    begin=next(x['at'] for x in f['missionFrames'] if x['phase']=='handover')-100;end=next(e['at'] for e in events if e['type']=='l1.infectedExit')+2000
   elif row['level']=='L7':
    pickup=next(e['at'] for e in events if e['type']=='pickup.collected' and e.get('actionId')=='weapon.rocket-launcher');rocket=next(e['at'] for e in events if e['type']=='combat.attack' and e.get('actionId')=='weapon.rocket-launcher' and e.get('sourceId')==1)
    impact=next(e['at'] for e in events if e['type']=='explosion' and e.get('defId')=='explosion.rocket' and e.get('sourceId')==1 and e['at']>=rocket)
    begin=(rocket if kind=='first rocket' else pickup)-100;end=(pickup if kind=='pickup' else impact)+250
    check(rocket>=pickup,'L7 rocket follows collection '+side+' '+row['tier'])
   else:begin=0;end=next(x['at'] for x in f['chargeFrames'] if x['charge']>=3600)+2000
   check(end<=f['durationMs'],'complete requested event span '+str((side,row['level'],row['tier'],kind)))
   clock=f['missionFrames'] if row['level']!='L10' else f['chargeFrames'];indices=[i for i,x in enumerate(clock) if x['at']>=begin and x['at']-f['frames'][i]<=end]
   v=stats([f['frames'][i] for i in indices]);values[side]=v;w=row['windows'][side]
   check(w['indices']==indices and w['startMs']==begin and w['endMs']==end and w['stats']==v and row['sides'][side]==v,'exact event-frame overlap selection '+str((side,row['level'],row['tier'],kind)))
  p,c=values['prod'],values['candidate'];issues=[]
  if c['p95']>p['p95']+1+1e-6:issues.append('p95 > PROD+1 ms')
  if c['maximum']>p['maximum']+16.8+1e-6:issues.append('max > PROD+1 frame')
  if c['maximum']>=66-1e-6 and p['maximum']<66-1e-6:issues.append('new >=66 ms spike')
  check(row['issues']==issues and row['verdict']==('FAIL' if issues else 'PASS'),'independent event verdict '+str((row['level'],row['tier'],kind)))
 g01=next(r for r in loads if (r['side'],r['level'],r['tier'],r['backend'],r['temperature'])==('candidate','L1','low','webgl2','cold'))
 check(g01['begin'] and g01['ms']<=6000,'G-01 cold L1 low WebGL2 Begin-ready <=6 seconds')
 verdictSets[prefix or 'initial']={'matrix':dict(collections.Counter(r['verdict'] for r in matrix['matrix'])),'moments':dict(collections.Counter(r['verdict'] for r in matrix['moments']))}
audit_dataset('','index-DnjIp4Ne.js',read('moment-native.json'))
audit_dataset('final-',prov['finalBundle'],[])
initial=prov['initialSource'];check(initial['diff']=='','initial public build starts from clean source')
for name,digest in initial['hashes'].items():
 raw=subprocess.check_output(['git','show',initial['revision']+':'+name]);check(hashlib.sha256(raw).hexdigest()==digest,'initial source identity '+name)
eq=read('frozen-equivalence.json');check(eq['cases']==288 and eq['bitIdenticalCases']==288,'all 288 actual-asset frozen geometry cases are bit identical')
check(eq['afterSourceSha256']==prov['sourceHashes']['src/render/characters/StaticCorpses.ts'] and eq['beforeSourceSha256']==initial['hashes']['src/render/characters/StaticCorpses.ts'],'equivalence identities match before/fixed source')
check(eq['speedup']>1 and eq['poseSpeedup']>1,'both CPU preparation fixes improve in measured benchmark')
check(eq['poseCases']==24 and eq['bitIdenticalPoseCases']==24 and eq['helperCases']==72 and eq['helperVertices']>0,'repaired clips and full/vertical skin matrices remain bit identical')
for stem,identities in eq['sourceIdentities'].items():
 name='src/render/characters/'+stem+'.ts';check(identities['before']==initial['hashes'][name] and identities['after']==prov['sourceHashes'][name],'equivalence source pair '+stem)
changed=subprocess.check_output(['git','diff','--name-only',initial['revision'],'HEAD','--','src'],text=True).splitlines();check(changed==['src/render/characters/StaticCorpses.ts','src/render/characters/deathPose.ts','src/render/characters/skinnedCrowd.ts'],'only the three bounded CPU preparation files changed')
validation=read('validation.json');check(len(validation)==4 and all(x['exitCode']==0 for x in validation),'all four required validation commands succeed')
check(not req['badResponses'] and not req['prodPathsMissingFromMirror'] and not req['selectedLoadBadResponses'] and not req['selectedLoadExternalURLs'],'all runtime requests succeed and mirror covers PROD')
mirror=read('mirror-audit.json');check(mirror['files']==2756 and mirror['assetVersionPaths']==2074 and not mirror['rehashFailures'] and not mirror['assetVersionMismatches'],'all mirror bytes and embedded asset versions verified')
check(prov['liveIndexUnchanged'] and prov['sourceChanges']=='','live index and candidate game source unchanged')
check(prov['build']['exitCode']==0 and prov['build']['revision']==prov['revision'] and len(prov['publicHookExclusion'])==1,'fresh production build and QA-hook exclusion')
for name,digest in prov['sourceHashes'].items():check(sha(pathlib.Path(name))==digest,'source freshness '+name)
for row in read('runs.json'):check(row['exitCode']==0,'terminal successful measurement command '+row['label'])
conditions=read('conditions.json')
for source in sorted({r['source'] for r in conditions}):
 rows=[r for r in conditions if r['source']==source]; admitted=[r for r in rows if r.get('pool') is True]
 check(len(admitted)==1 and rows[-1]==admitted[0],'one terminal quiet admission '+source)
 row=admitted[0];check(row['quiet'] and not row.get('busy',[]) and row['load'][0]<3,'quiet admission '+source)
 check(all(r.get('event')=='quiet-admission-wait' for r in rows[:-1]),'preceding samples are admission waits '+source)
for row in read('raw-manifest.json'):
 p=pathlib.Path(row['path'])
 if p.exists():check(p.stat().st_size==row['bytes'] and sha(p)==row['sha256'],'raw evidence hash '+str(p))
receipt=dict(at=datetime.datetime.now(datetime.timezone.utc).isoformat(),passAudit=True,checks=len(checks),messages=checks,datasets=verdictSets)
(O/'audit.json').write_text(json.dumps(receipt,indent=2)+'\n');print({k:v for k,v in receipt.items() if k!='messages'})

