  const row = (at) => mat4(column(at, 0), column(at, 1), column(at, 2), column(at, 3));
  return Fn(() => {
    const result = row(low).toVar();
    If(alpha.greaterThan(0), () => {
      result.assign(result.mul(alpha.oneMinus()).add(row(low.add(1)).mul(alpha)));
    });
    return result;
  })();
