    const current = crowdMatrix(texture, part, frame).toVar();
    If(weight.lessThan(1), () => {
      current.assign(crowdMatrix(texture, part, outgoing).mul(weight.oneMinus()).add(current.mul(weight)));
    });
    return current;
  })();
}

