    if (owners) {
      const at = order.findIndex((k) => indices[i * 4 + k] === owners[i] && weights[i * 4 + k] > 0);
      if (at < 0) throw Error("Crowd semantic owner must be a weighted joint");
      order.unshift(order.splice(at, 1)[0]);
    }
